const ll MOD = 1000000007;

struct State {
    ll count = 0;
    ll sum = 0;
};

ll prefixSum(ll xCount, ll yCount, ll k) {
    if (xCount <= 0 || yCount <= 0 || k <= 0) return 0;

    const ll xBound = xCount - 1;
    const ll yBound = yCount - 1;
    const ll kBound = k - 1;

    State dp[2][2][2]{};
    dp[1][1][1].count = 1;

    ll powers[63];
    powers[0] = 1;
    for (int i = 1; i < 63; ++i) {
        powers[i] = powers[i - 1] * 2 % MOD;
    }

    for (int bit = 62; bit >= 0; --bit) {
        State next[2][2][2]{};

        const int xb = (xBound >> bit) & 1;
        const int yb = (yBound >> bit) & 1;
        const int kb = (kBound >> bit) & 1;

        for (int tx = 0; tx < 2; ++tx) {
            for (int ty = 0; ty < 2; ++ty) {
                for (int tk = 0; tk < 2; ++tk) {
                    const State current = dp[tx][ty][tk];
                    if (current.count == 0) continue;

                    for (int dx = 0; dx <= 1; ++dx) {
                        if (tx && dx > xb) continue;

                        for (int dy = 0; dy <= 1; ++dy) {
                            if (ty && dy > yb) continue;

                            const int dz = dx ^ dy;
                            if (tk && dz > kb) continue;

                            const int ntx = tx && (dx == xb);
                            const int nty = ty && (dy == yb);
                            const int ntk = tk && (dz == kb);

                            State &target = next[ntx][nty][ntk];
                            target.count =
                                (target.count + current.count) % MOD;

                            target.sum =
                                (target.sum + current.sum +
                                 current.count * dz % MOD * powers[bit]) % MOD;
                        }
                    }
                }
            }
        }

        memcpy(dp, next, sizeof(dp));
    }

    ll count = 0;
    ll sum = 0;

    for (int tx = 0; tx < 2; ++tx) {
        for (int ty = 0; ty < 2; ++ty) {
            for (int tk = 0; tk < 2; ++tk) {
                count = (count + dp[tx][ty][tk].count) % MOD;
                sum = (sum + dp[tx][ty][tk].sum) % MOD;
            }
        }
    }

    return (sum + count) % MOD;
}

